CREATE DATABASE IF NOT EXISTS mindspace CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mindspace;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE journals(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(200) NOT NULL,entry_date DATE NOT NULL,content TEXT NOT NULL,mood VARCHAR(40) DEFAULT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE moods(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,mood_date DATE NOT NULL,mood VARCHAR(40) NOT NULL,note VARCHAR(500) DEFAULT '',UNIQUE(user_id,mood_date),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE habits(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,name VARCHAR(120) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE habit_logs(id INT AUTO_INCREMENT PRIMARY KEY,habit_id INT NOT NULL,log_date DATE NOT NULL,completed TINYINT(1) DEFAULT 1,UNIQUE(habit_id,log_date),FOREIGN KEY(habit_id) REFERENCES habits(id) ON DELETE CASCADE);
CREATE TABLE trackers(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,tracker_type ENUM('reading','sleep','screen_time','savings') NOT NULL,record_date DATE NOT NULL,value DECIMAL(10,2) NOT NULL,details VARCHAR(255) DEFAULT '',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE goals(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(160) NOT NULL,target DECIMAL(10,2) NOT NULL,current_value DECIMAL(10,2) DEFAULT 0,deadline DATE NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
